mapper.select:
select distinct ee.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId/*资产代码*/, fp.FINPROD_ABBR finprodAbbr/*资产简称*/, fp.COUPON_SPECIES couponSpecies/*息票品种*/, fp.TRADE_MARKET tradeMarket/*交易场所*/, fp.REGIST_ORG registOrg, #{loginUserId} ourTrader/*本方交易员*/, ee.COUNTER_ID counterId/*交易对手*/, MCP.COUNTER_NAME counterName/*交易对手*/, fpi.TENDER_TARGET tenderTarget/*招标标的*/, fp.CCY ccy /*币种*/, CASE WHEN fpi.ISSUE_CLASS = #{ISSUE_CLASS_02} AND fpi.TENDER_TYPE IN (#{TENDER_TYPE_01}, #{TENDER_TYPE_02}) THEN fpi.ISSUE_DATE WHEN (fpi.ISSUE_CLASS = #{ISSUE_CLASS_02} AND (fpi.TENDER_TYPE IS NULL OR fpi.TENDER_TYPE IN (#{TENDER_TYPE_03}, #{TENDER_TYPE_04}))) OR fpi.ISSUE_CLASS = #{ISSUE_CLASS_03} THEN fpi.TENDER_SDATE END AS bidDateStart/*投标日 开始*/, CASE WHEN fpi.ISSUE_CLASS = #{ISSUE_CLASS_02} AND fpi.TENDER_TYPE IN (#{TENDER_TYPE_01}, #{TENDER_TYPE_02}) THEN null WHEN (fpi.ISSUE_CLASS = #{ISSUE_CLASS_02} AND (fpi.TENDER_TYPE IS NULL OR fpi.TENDER_TYPE IN (#{TENDER_TYPE_03}, #{TENDER_TYPE_04}))) OR fpi.ISSUE_CLASS = #{ISSUE_CLASS_03} THEN fpi.TENDER_EDATE END AS bidDateEnd/*投标日 结束*/, case when fpi.PAY_EDATE is not null then fpi.PAY_EDATE else fpi.PAY_DATE end payEdate/*缴款截止日*/, case when fpi.PAY_DATE is not null then fpi.PAY_DATE else fpi.PAY_EDATE end payDate/*缴款日*/, fpi.ASSIGN_REGDATE assignRegdate/*债权债务登记日*/, CASE WHEN fp.CIRCULATION_DATE IS NOT NULL THEN fp.CIRCULATION_DATE ELSE fpa.LISTING_DATE end AS listingDate/*上市日*/, fp.CIRCULATION_DATE circulationDate /*上市流通日*/, CASE WHEN ( fpi.ISSUE_CLASS = #{ISSUE_CLASS_02} AND fpi.TENDER_TYPE IN (#{TENDER_TYPE_01}, #{TENDER_TYPE_02}) AND fpi.ISSUE_DATE < TO_DATE(#{sysDate,jdbcType=VARCHAR},'YYYY-MM-DD') ) OR (((fpi.ISSUE_CLASS = #{ISSUE_CLASS_02} AND (fpi.TENDER_TYPE IS NULL OR fpi.TENDER_TYPE IN (#{TENDER_TYPE_03}, #{TENDER_TYPE_04})) ) OR fpi.ISSUE_CLASS = #{ISSUE_CLASS_03} ) AND fpi.TENDER_EDATE < TO_DATE(#{sysDate,jdbcType=VARCHAR},'YYYY-MM-DD') ) THEN #{WIN_TYPE_03} ELSE #{WIN_TYPE_01} END AS biddingMethod/*投标方式*/, ee.ENTRUST_ID/*指令代码*/, eed.PORTFOLIO_ID, pp.PORTFOLIO_NAME/*组合名称*/, eed.ACCT_NO/*资金账户*/, case when fpi.TENDER_TARGET = '01' then eebp.BID_PRICE * 100 when fpi.TENDER_TARGET = '02' then eebp.BID_PRICE when fpi.TENDER_TARGET = '03' then eebp.BID_PRICE * 10000 end BID_PRICE/*投标标位*/, eed.INV_AIM/*业务模式*/, eed.SEC_ACCT_ID/*证券账户*/, ssai.SEC_ACCT_NAME/*证券账户*/, ee.INV_MANAGER_ID/*投资经理ID*/, SU.REAL_NAME INV_MANAGER_NAME/*投资经理*/, nvl(nvl(eebp.BID_PRIN_AMT,0)*100 - nvl(T.finshNum,0),0) avaNum /*剩余券面总额*/, eebp.BID_PRIN_AMT*100 ENTRUST_NUM /*委托投标券面*/ from ETR_ENTRUST ee left join ETR_ENTRUST_DETAIL eed on ee.ENTRUST_ID = eed.ENTRUST_ID left join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = eed.PORTFOLIO_ID left join ETR_ENTRUST_BID_PRICE eebp on eebp.ENTRUST_ID = ee.ENTRUST_ID and eed.PORTFOLIO_ID = eebp.PORTFOLIO_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.FINPROD_ID left join FIN_PRODUCT_ADD fpa on fpa.FINPROD_ID = ee.FINPROD_ID left join FIN_PRODUCT_ISSUE fpi on fpi.FINPROD_ID = ee.FINPROD_ID LEFT JOIN SYS_USER SU ON ee.INV_MANAGER_ID = SU.USER_NAME LEFT JOIN STL_SEC_ACCT_INFO ssai ON eed.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN MST_COUNTER_PARTY MCP ON ee.COUNTER_ID = MCP.COUNTER_ID left join (select sum(nvl(THE_WIN_PRIN_AMT, 0)) finshNum, ENTRUST_ID, PORTFOLIO_ID, BID_PRICE from BID_ORDER_BID_PRICE where IS_CANCEL = 'N' and TRADE_STATUS = '01' group by ENTRUST_ID, PORTFOLIO_ID, BID_PRICE) T on T.ENTRUST_ID = eebp.ENTRUST_ID and T.PORTFOLIO_ID = eebp.PORTFOLIO_ID and T.BID_PRICE = eebp.BID_PRICE
ee.ENTRUST_ID in
#{item}

select distinct ENTRUST_ID from ( select distinct bo.BID_ID,bobp.ENTRUST_ID from BID_ORDER bo left join BID_ORDER_BID_PRICE bobp on bo.BID_ID = bobp.BID_ID where bo.IS_CANCEL = 'N' and bo.TRADE_STATUS = '01'
and bo.BID_MODLE in
#{item}
and bobp.ENTRUST_ID in
#{item}
union all select distinct bo.BID_ID,bobp.ENTRUST_ID from Wfl_BID_ORDER bo left join Wfl_BID_ORDER_BID_PRICE bobp on bo.BID_ID = bobp.BID_ID where bo.IS_CANCEL = 'N' and bo.TRADE_STATUS = '01'
and bo.BID_MODLE in
#{item}
and bobp.ENTRUST_ID in
#{item}
)

select entrustStatus, firstBidStatus, issueDateStart, issueDateEnd, counterId,counterName , entrustId , entrustIdKey from ( select ee.ENTRUST_STATUS entrustStatus, CASE WHEN (bobrt.BID_MODLE IS NOT NULL AND bobrt.BID_MODLE = '03') OR bobrt.IS_WIN = 'Y' THEN '04' WHEN bobrt.BID_MODLE IS NULL THEN '01' WHEN bobrt.IS_WIN = 'N' THEN '03' WHEN (bobrt.BID_MODLE IN ('01', '02') AND bobrt.IS_WIN IS NULL) THEN '02' ELSE '05' END AS firstBidStatus, CASE WHEN fpi.ISSUE_CLASS = '02' AND fpi.TENDER_TYPE IN ('01', '02') THEN fpi.ISSUE_DATE WHEN (fpi.ISSUE_CLASS = '02' AND (fpi.TENDER_TYPE IS NULL OR fpi.TENDER_TYPE IN ('03', '04'))) OR fpi.ISSUE_CLASS = '03' THEN fpi.TENDER_SDATE END AS issueDateStart/*投标日 开始*/, CASE WHEN fpi.ISSUE_CLASS = '02' AND fpi.TENDER_TYPE IN ('01', '02') THEN null WHEN (fpi.ISSUE_CLASS = '02' AND (fpi.TENDER_TYPE IS NULL OR fpi.TENDER_TYPE IN ('03', '04'))) OR fpi.ISSUE_CLASS = '03' THEN fpi.TENDER_EDATE END AS issueDateEnd/*投标日 结束*/, ee.COUNTER_ID counterId, mcp.COUNTER_NAME counterName, ee.ENTRUST_ID entrustId, teer.TOTLE_ID entrustIdKey from ETR_ENTRUST ee left join MST_COUNTER_PARTY mcp ON mcp.COUNTER_ID = ee.COUNTER_ID LEFT JOIN ( SELECT bo.BID_MODLE, brt.IS_WIN, bo.FINPROD_ID, bobp.ENTRUST_ID FROM BID_ORDER bo LEFT JOIN BID_ORDER_BID_PRICE bobp ON bobp.BID_ID = bo.BID_ID LEFT JOIN BID_RESULT_TOTAL brt ON brt.BID_ID = bo.BID_ID AND brt.STATUS = '01' AND brt.FINPROD_ID = bo.FINPROD_ID WHERE bo.IS_CANCEL = 'N' AND bo.TRADE_STATUS = '01' GROUP BY bo.BID_MODLE, brt.IS_WIN, bo.FINPROD_ID, bobp.ENTRUST_ID ) bobrt ON bobrt.FINPROD_ID = ee.FINPROD_ID AND bobrt.ENTRUST_ID = ee.ENTRUST_ID left join FIN_PRODUCT_ISSUE fpi on fpi.FINPROD_ID = ee.FINPROD_ID left join TOTAL_ETR_ENTRUST_REL teer on ee.ENTRUST_ID = teer.ENTRUST_ID where fpi.ISSUE_CLASS in (#{ISSUE_CLASS_02}, #{ISSUE_CLASS_03}) and ee.FINPROD_ID = #{finprodId} and not exists( select 1 from BID_ORDER bo left join BID_ORDER_BID_PRICE bobp on bo.BID_ID = bobp.BID_ID where bo.IS_CANCEL = 'N' and bo.TRADE_STATUS = '01' and bobp.ENTRUST_ID = ee.ENTRUST_ID
and bo.BID_MODLE in
#{item}
) and not exists( select 1 from Wfl_BID_ORDER_BID_PRICE bobp where bobp.ENTRUST_ID = ee.ENTRUST_ID )
and ee.COUNTER_ID = #{counterId}
and teer.TOTLE_ID = #{totleId}
)
and issueDateEnd = #{issueDateEnd}
and issueDateStart = #{issueDateStart}

select count(*) num
from BID_RESULT_TOTAL
where BID_ID = #{bidId}
